"""LiveService per-request generator override + usage sink."""

from __future__ import annotations

import json
from typing import Any

from app.retrieval.live_service import LiveService
from app.retrieval.models import AskParameters

_LIVE_RESPONSE = json.dumps(
    {
        "answer_status": "answered",
        "answer": "Generated by the override model.",
        "citations": [],
        "decisions": [],
        "graph_path": [],
        "caveats": [],
        "confidence": "high",
    }
)


class _FakeGenerator:
    def __init__(self, text: str) -> None:
        self._text = text
        self.last_usage: dict[str, Any] | None = None
        self.calls = 0

    def complete(self, *, system: str, user: str, schema: dict, schema_name: str) -> str:
        self.calls += 1
        self.last_usage = {"prompt_tokens": 10, "completion_tokens": 5, "total_tokens": 15}
        return self._text


def test_override_generator_serves_the_call_and_fills_the_sink() -> None:
    service = LiveService(generator=None)
    override = _FakeGenerator(_LIVE_RESPONSE)
    sink: dict[str, int] = {}
    response = service.answer_question(
        AskParameters(question="Why retries?", repo="encode/httpx"),
        generator=override,
        usage_sink=sink,
    )
    assert response.answer == "Generated by the override model."
    assert override.calls == 1
    assert sink == {
        "prompt_tokens": 10,
        "completion_tokens": 5,
        "total_tokens": 15,
        "calls": 1,
    }
    # The service default is untouched by the per-request override.
    assert service.generator is None


def test_service_default_generator_is_used_without_an_override() -> None:
    default = _FakeGenerator(_LIVE_RESPONSE)
    service = LiveService(generator=default)
    sink: dict[str, int] = {}
    service.answer_question(
        AskParameters(question="Why retries?", repo="encode/httpx"),
        usage_sink=sink,
    )
    assert default.calls == 1
    assert sink["total_tokens"] == 15
